{
  "verdict": "request_changes",
  "summary": "The candidate implementation fails to invalidate the cache when a SKU price is updated, leading to stale data and violating the specification.",
  "findings": [
    {
      "finding_id": "C001",
      "file": "candidate.py",
      "line_start": 16,
      "line_end": 19,
      "severity": "high",
      "description": "update_price does not clear or update the cached value for the SKU, so subsequent price() calls return the old cached price instead of the new value.",
      "evidence": "catalog = candidate.Catalog({\"a\": 100})\ncatalog.price(\"a\")  # caches 100\ncatalog.update_price(\"a\", 200)\nprint(catalog.price(\"a\"))  # still outputs 100, not 200, violating the contract."
    }
  ]
}
